<template>
  <div class="choice_vote_box" :style="is_focus_width?'width: 680px;':'width: 640px;'"  @click="choice_vote_click">
      <div class="tip_box" :class="{'choose_box':voteOrder===choose_order}" ref="vote_order">
        <el-row>
          <el-col :span="1" class="tip_sort">
            {{voteOrder}}.
          </el-col>
          <el-col :span="23" class="tip_info">
            <div @mouseover="hover_info" @mouseleave="leave_info">
              <el-input
                class="ant-input_title" :class="{'gray_line': dec_gray_line, 'choose_line': dec_choose_line}"
                type="textarea"
                :autosize="{ minRows: 1, maxRows: 10}"
                placeholder="输入问题"
                @focus="tip_focus(voteOrder)"
                maxlength="1000"
                v-model="vote_block_msg.block_title">
              </el-input>
            </div>
          </el-col>
        </el-row>

        <el-row v-if="vote_block_msg && vote_block_msg.info_options" v-for="(item, index) in vote_block_msg.info_options">
          <el-col :span="23" class="tip_options_info normal_msg" v-if="0==item.option_type">
            <el-radio disabled v-if="3==vote_block_msg.block_type">
              <textarea maxlength="300" :autosize="{minRows:1,maxRows:2}" v-model="item.option_name" class="ant-input" :class="(index==gray_line_options)?'gray_line_options':((choose_line_options==index)?'choose_line_options':'')" :placeholder="item.label+(index+1)" @focus="tip_options_focus(index)" @mouseover="hover_tip_options(index)" @mouseleave="leave_tip_options(index)"></textarea>
            </el-radio>
            <el-checkbox disabled v-if="4==vote_block_msg.block_type">
              <textarea maxlength="300" :autosize="{minRows:1,maxRows:2}" v-model="item.option_name" class="ant-input" :class="(index==gray_line_options)?'gray_line_options':((choose_line_options==index)?'choose_line_options':'')" :placeholder="item.label+(index+1)" @focus="tip_options_focus(index)" @mouseover="hover_tip_options(index)" @mouseleave="leave_tip_options(index)"></textarea>
            </el-checkbox>
          </el-col>
          <el-col :span="23" class="tip_options_info" v-if="1==item.option_type">
            <el-radio disabled  v-if="3==vote_block_msg.block_type">
              <span class="other_info">其他</span>&nbsp;&nbsp;&nbsp;<input class="tip_content_single" disabled="" placeholder="填写者回答区">
            </el-radio>
            <el-checkbox disabled v-if="4==vote_block_msg.block_type">
              <span class="other_info">其他</span>&nbsp;&nbsp;&nbsp;<input class="tip_content_single" disabled="" placeholder="填写者回答区">
            </el-checkbox>
          </el-col>
          <el-col :span="1" class="tip_info" v-show="tip_set">
            <div @click="del_options(index)">
              <i class="el-icon-close"></i>
            </div>
          </el-col>
        </el-row>

        <el-row class="tip_set" v-show="tip_set">
          <el-col :span="3" class="add_icon">
            <div @click="add_option(0)">
              <i class="el-icon-plus"></i><span>添加选项</span>
            </div>
          </el-col>
          <el-col :span="5" class="add_icon" v-show="!vote_block_msg.is_other_options">
            <div @click="add_option(1)">
              <i class="el-icon-plus"></i><span>添加“其他”选项</span>
            </div>
          </el-col>
          <el-col :span="!vote_block_msg.is_other_options?16:21" class="set_box">
            <el-select size="mini" class="tip_block_type" v-model="vote_block_msg.block_type" placeholder="单选">
              <el-option
                v-for="item in block_type_options"
                :key="item.value"
                :label="item.label"
                :value="item.value">
              </el-option>
            </el-select>
            &nbsp;&nbsp;
            <el-switch
              inactive-text="必填"
              v-model="vote_block_msg.is_write"
              active-color="#1890ff"
              inactive-color="#DCDFE6"
              active-value="1"
              inactive-value="2">
            </el-switch>
            <el-tag @click="copy_tip">复制</el-tag>
            <el-tag v-if="voteOrder>1" @click="move_tip('up')">上移</el-tag>
            <el-tag v-if="voteOrder < block_length" @click="move_tip('down')">下移</el-tag>
            <el-tag type="info" @click="del_tip">删除</el-tag>
          </el-col>
        </el-row>
      </div>
  </div>
</template>

<script>
  export default {
    name:'completion_vote',
    data () {
      return {
        gray_line_options: -1,
        choose_line_options: -1,
        dec_gray_line: false,
        is_focus_width: false,
        dec_choose_line: false,
        tip_set: false,
        tip_box_class: '',
        choose_order: '',
        is_other_options_key: -1,
        block_type_options: [{
          value: '3',
          label: '单选'
        }, {
          value: '4',
          label: '多选'
        }],
      }
    },
    computed: {
      vote_block_msg: function () {
        return this.vote_block;
      }
    },
    methods: {
      choice_vote_click: function (e) {
        this.choose_order = this.voteOrder;
        this.tip_set = true;
        this.is_focus_width = true;
      },
      add_option: function (option_type) {
        let option_name = '';
        let label = '';
        let len = this.vote_block_msg.info_options.length;
        let other_options = '';
        console.log('is_other_options',this.vote_block_msg.is_other_options);
        console.log('is_other_options_key',this.is_other_options_key);
        console.log('is_other_options_key',this.is_other_options_key);
        if (this.vote_block_msg && this.vote_block_msg.is_other_options && this.is_other_options_key>-1) {
          other_options = this.vote_block_msg.info_options[this.is_other_options_key];
          console.log('other_options',other_options);
          this.vote_block_msg.info_options.splice(this.is_other_options_key,1);
          this.is_other_options_key = len;
        }
        if (0==option_type) {
          option_name='';
          label='选项';
        } else {
          this.vote_block_msg.is_other_options=true;
          this.is_other_options_key = len;
          option_name='其他';
          label='其他';
        }
        let msg = {
          value: len-1,
          label:label,
          option_name:option_name,
          option_type:option_type
        };
        this.vote_block_msg.info_options.push(msg);
        if (other_options) {
          this.vote_block_msg.info_options.push(other_options);
        }
      },
      tip_focus: function (voteOrder) {
        this.dec_choose_line = true;
        this.dec_gray_line = false;
        this.gray_line_options = -1;
        this.choose_line_options = -1;
        this.$parent.change_click_msg('vote_order', voteOrder-1);
      },
      tip_options_focus: function(index) {
        this.gray_line_options = -1;
        this.choose_line_options = index;
        this.dec_choose_line = false;
        this.dec_gray_line = false;
        this.$parent.change_click_msg('vote_order', this.voteOrder-1);
      },
      copy_tip: function () {
        this.$parent.copy_tip(this.voteOrder,this.vote_block_msg, 2);
      },
      move_tip: function (msg) {
        this.$parent.move_tip(this.voteOrder,msg);
      },
      change_vote_order: function (target_msg) {
        console.log('子组件被调用',this.voteOrder)
        let sp = this.$refs.vote_order;
        if(sp){
          if(!sp.contains(target_msg) && this.voteOrder>0){
            this.change_cancel()
          } else {
            this.$parent.set_vote_order(this.voteOrder-1);
          }
        }
      },
      change_cancel: function () {
        this.choose_order = 0;
        this.tip_set = false;
        this.dec_choose_line = false;
        this.dec_gray_line = false;
        this.is_focus_width = false;
        this.gray_line_options = -1;
        this.choose_line_options = -1;
      },
      hover_info(e) {
        console.log('覆盖')
        this.dec_gray_line = true;
      },
      leave_info(e) {
        console.log('离开')
        if(e.target && this.dec_gray_line){
          this.dec_gray_line = false;
        }
      },
      hover_tip_options(index) {
        if(this.gray_line_options==-1){
          this.gray_line_options = index;
        }
      },
      leave_tip_options(index) {
        if(this.gray_line_options>-1){
          this.gray_line_options = -1;
        }
      },
      del_options(index) {
        // 删一个数组元素
        console.log('删一个数组元素',index);
        let len = this.vote_block_msg.info_options.length;
        if (len<=2) {
          this.$message({
            message: '至少设置两个选项',
            type: 'warning'
          });
          return false;
        }
        if (this.vote_block_msg.info_options[index] && 1==this.vote_block_msg.info_options[index]['option_type']) {
          this.vote_block_msg.is_other_options=false;
          this.is_other_options_key = -1;
        } else {
          this.is_other_options_key = len-2;
        }
        this.vote_block_msg.info_options.splice(index,1);
      },
      del_tip(e) {
        console.log('删除',this.block)
        if(e.target && this.voteOrder){
          this.$parent.deleteTip(this.voteOrder-1);
        }
      }
    },
    props: ["vote-order",'block_length','vote_block']
  }
</script>

