    padding: 30px 0;
  }
  .choice_vote_box .hide {
    display: none;
  }

  .choice_vote_box .tip_box {
    width: 100%;
    line-height: 32px;
  }

  .choice_vote_box .tip_sort {
    text-align: left;
    color: #3d4757;
    font-size: 16px;
    line-height: 32px;
  }
  .choice_vote_box textarea {
    overflow: auto;
  }
  .choice_vote_box *, :after, :before {
    -webkit-tap-highlight-color: rgba(0,0,0,0);
  }
  .choice_vote_box *, :after, :before {
    -webkit-box-sizing: border-box;
    box-sizing: border-box;
  }
  .choice_vote_box textarea::-webkit-input-placeholder{
    color: #aeb5c0;
    font-size: 12px;
  }
  .choice_vote_box .tip_options_info textarea::-webkit-input-placeholder{
    color: #aeb5c0;
    font-size: 12px;
    font-weight: normal;
  }
  .choice_vote_box .tip_content {
    color: #aeb5c0;
    border-bottom: 1px dashed #e2e6ed;
  }
  .choice_vote_box .tip_content_single {
    background: #fff;
    padding: 0 0 6px;
    color: #aeb5c0;
    font-weight: normal;
    margin-top: 16px;
    border: none;
    width: 93%;
    font-size: 12px;
    letter-spacing: 0;
    outline: none;
    border-bottom:1px solid #DCDFE6 ;
  }

  .choice_vote_box tip_content_single::-webkit-input-placeholder{
    color: #aeb5c0;
    font-size: 12px;
    font-weight: normal;
  }

  .choice_vote_box .tip_set {
    padding-top: 10px;
  }
  .choice_vote_box .tip_block_type {
    width: 5rem;
    height: 1.2rem;
  }



  .choice_vote_box .choose_box {
    -webkit-box-shadow: 0 4px 16px 0 rgba(192,198,207,.5);
    box-shadow: 0 4px 16px 0 rgba(192,198,207,.5);
    -webkit-border-radius: 2px;
    border-radius: 2px;
    z-index: 2;
    padding: 20px 20px;
    margin-bottom: 30px;
  }

  .choice_vote_box .ant-input.gray_line_options {
    border-bottom:1px solid #DCDFE6 ;
  }
  .choice_vote_box .ant-input.choose_line_options {
    border-bottom:1px solid #1890ff ;
  }

  .choice_vote_box .tip_options_info .el-radio {
    width: 95%;
  }
  .choice_vote_box .tip_options_info .el-checkbox {
    width: 95%;
  }


  .choice_vote_box .el-tag {
    cursor: pointer;
    margin-left: 5px;
  }
  .choice_vote_box .add_icon {
    cursor: pointer;
    font-size: 12px;color: #1890ff;
  }
  .choice_vote_box .other_info {
    cursor: pointer;
    font-size: 12px;color: #3d4757;
  }
  .choice_vote_box .set_box {
    text-align: right;
  }
</style>
