  .choice_vote_box .tip_options_info.normal_msg .el-radio__inner {
    bottom: 10px;
  }
  .choice_vote_box .tip_options_info.normal_msg .el-checkbox__inner {
    bottom: 10px;
  }
  .choice_vote_box .tip_options_info .el-checkbox__label {
    width: 100%;
  }

  .choice_vote_box .ant-input {
    font-variant: tabular-nums;
    margin: 0;
    list-style: none;
