    word-wrap:break-word;
  }

  .choice_vote_box .gray_line .el-textarea__inner {
    border-bottom:1px solid #DCDFE6;
  }
  .choice_vote_box .choose_line .el-textarea__inner {
    border-bottom:1px solid #1890ff;
